 386→/**
 387→ * Delete a folder and all its contents recursively.
 388→ *
 389→ * For v2 metadata: collects fileMetaIpnsName values from FilePointer children
 390→ * (not CIDs, since CIDs live in per-file IPNS records, not folder metadata).
 391→ * Removes the folder from the parent's metadata, publishes the update.
 392→ * Returns the collected file IPNS names so the caller can resolve them for
 393→ * CID unpinning and TEE unenrollment.
 394→ *
 395→ * @param params.folderId - ID of folder to delete
 396→ * @param params.parentFolderState - Parent folder containing this folder
 397→ * @param params.getFolderState - Function to get folder state by ID (for recursion)
 398→ * @throws Error if folder not found
 399→ */
 400→export async function deleteFolder(params: {
 401→  folderId: string;
 402→  parentFolderState: FolderNode;
 403→  getFolderState: (id: string) => FolderNode | undefined;
 404→}): Promise<{
 405→  fileIpnsNames: string[];
 406→  newSequenceNumber: bigint;
 407→  removedChild: FolderEntry;
 408→}> {
 409→  // 1. Find folder in parent's children
 410→  const children = [...params.parentFolderState.children];
 411→  const folderIndex = children.findIndex((c) => c.type === 'folder' && c.id === params.folderId);
 412→
 413→  if (folderIndex === -1) throw new Error('Folder not found');
 414→
 415→  // Capture the removed FolderEntry before splicing (needed for bin service)
 416→  const removedChild = children[folderIndex] as FolderEntry;
 417→
 418→  // 2. Recursively collect file IPNS names for cleanup
 419→  // In v2, file children are FilePointers with fileMetaIpnsName (no inline CID).
 420→  // The caller must resolve each fileMetaIpnsName to get the CID for unpinning.
 421→  const fileIpnsNames: string[] = [];
 422→  const collectFileIpnsNames = (folderId: string) => {
 423→    const folder = params.getFolderState(folderId);
 424→    if (!folder) return;
 425→
 426→    for (const child of folder.children) {
 427→      if (child.type === 'file') {
 428→        const filePointer = child as FilePointer;
 429→        if (filePointer.fileMetaIpnsName) {
 430→          fileIpnsNames.push(filePointer.fileMetaIpnsName);
 431→        }
 432→      } else if (child.type === 'folder') {
 433→        collectFileIpnsNames(child.id);
 434→      }
 435→    }
 436→  };
 437→
 438→  collectFileIpnsNames(params.folderId);
 439→
 440→  // 3. Remove folder from parent's children
 441→  children.splice(folderIndex, 1);
 442→
 443→  // 4. Update parent folder metadata and publish
 444→  const { newSequenceNumber } = await updateFolderMetadata({
 445→    folderId: params.parentFolderState.id,
 446→    children,
 447→    folderKey: params.parentFolderState.folderKey,
 448→    ipnsPrivateKey: params.parentFolderState.ipnsPrivateKey,
 449→    ipnsName: params.parentFolderState.ipnsName,
 450→    sequenceNumber: params.parentFolderState.sequenceNumber,
 451→  });
 452→
 453→  // 5. File CID unpinning and TEE unenrollment deferred to caller
 454→  // The caller (useFolder hook) resolves fileMetaIpnsName -> CID for unpinning.
 455→  // TODO: Phase 14 should add batch unenrollment for orphaned file IPNS records.
 456→
 457→  return { fileIpnsNames, newSequenceNumber, removedChild };
 458→}
 459→
 460→/**
 461→ * Delete a file from its parent folder (v2).
 462→ *
 463→ * Removes the FilePointer from the parent's metadata, publishes the update.
 464→ * Returns the fileMetaIpnsName so the caller can resolve it for CID unpinning
 465→ * and TEE unenrollment.
 466→ *
 467→ * Note: This handles folder metadata update. File CID unpinning is handled
 468→ * by the caller after resolving the file metadata.
 469→ *
 470→ * @param params.fileId - ID of file to delete
 471→ * @param params.parentFolderState - Parent folder containing this file
 472→ * @returns fileMetaIpnsName for caller to handle cleanup
 473→ * @throws Error if file not found
 474→ */
 475→export async function deleteFileFromFolder(params: {
 476→  fileId: string;
 477→  parentFolderState: FolderNode;
 478→}): Promise<{
 479→  fileMetaIpnsName: string | undefined;
 480→  newSequenceNumber: bigint;
 481→  removedChild: FilePointer;
 482→}> {
 483→  // 1. Find file in parent's children
 484→  const children = [...params.parentFolderState.children];
 485→  const fileIndex = children.findIndex((c) => c.type === 'file' && c.id === params.fileId);
 486→
 487→  if (fileIndex === -1) throw new Error('File not found');
 488→
 489→  // 2. Capture the removed FilePointer before splicing (needed for bin service)
 490→  const removedChild = children[fileIndex] as FilePointer;
 491→  const fileMetaIpnsName = removedChild.fileMetaIpnsName;
 492→
 493→  // 3. Remove file from parent's children
 494→  children.splice(fileIndex, 1);
 495→
 496→  // 4. Update parent folder metadata and publish
 497→  const { newSequenceNumber } = await updateFolderMetadata({
 498→    folderId: params.parentFolderState.id,
 499→    children,
 500→    folderKey: params.parentFolderState.folderKey,
 501→    ipnsPrivateKey: params.parentFolderState.ipnsPrivateKey,
 502→    ipnsName: params.parentFolderState.ipnsName,
 503→    sequenceNumber: params.parentFolderState.sequenceNumber,
 504→  });
 505→
 506→  // 5. TEE unenrollment: no API endpoint available yet.
 507→  // TODO: Phase 14 should expose unenrollIpns via REST API.
 508→  if (fileMetaIpnsName) {
 509→    console.warn(
 510→      `File IPNS record ${fileMetaIpnsName} orphaned after deletion. TEE unenrollment deferred to Phase 14.`
 511→    );
 512→  }
 513→
 514→  return { fileMetaIpnsName, newSequenceNumber, removedChild };
 515→}
