 517→/**
 518→ * Add a file to a folder after successful upload (v2).
 519→ *
 520→ * Creates a FilePointer from the file's IPNS record and adds it to the folder's
 521→ * children array. Publishes both the file IPNS record and the updated folder
 522→ * metadata via a single batch API call.
 523→ *
 524→ * @param params.parentFolderState - Parent folder to add file to
 525→ * @param params.fileId - Pre-generated file UUID
 526→ * @param params.name - Original file name
 527→ * @param params.fileIpnsRecord - File IPNS record payload from createFileMetadata
 528→ * @returns Created file pointer and new sequence number
 529→ * @throws Error if name collision exists
 530→ */
 531→export async function addFileToFolder(params: {
 532→  parentFolderState: FolderNode;
 533→  fileId: string;
 534→  name: string;
 535→  fileIpnsRecord: FileIpnsRecordPayload;
 536→  ipnsPrivateKeyEncrypted: string;
 537→}): Promise<{ filePointer: FilePointer; newSequenceNumber: bigint }> {
 538→  // 1. Check for name collision
 539→  const nameExists = params.parentFolderState.children.some((c) => c.name === params.name);
 540→  if (nameExists) {
 541→    throw new Error('A file with this name already exists');
 542→  }
 543→
 544→  // 2. Create FilePointer (slim reference to per-file IPNS record + wrapped key)
 545→  const now = Date.now();
 546→  const filePointer: FilePointer = {
 547→    type: 'file',
 548→    id: params.fileId,
 549→    name: params.name,
 550→    fileMetaIpnsName: params.fileIpnsRecord.ipnsName,
 551→    ipnsPrivateKeyEncrypted: params.ipnsPrivateKeyEncrypted,
 552→    createdAt: now,
 553→    modifiedAt: now,
 554→  };
 555→
 556→  // 3. Add FilePointer to parent's children
 557→  const children: FolderChild[] = [...params.parentFolderState.children, filePointer];
 558→
 559→  // 4. Build folder IPNS record for batch publish
 560→  const folderResult = await buildFolderIpnsRecord({
 561→    children,
 562→    folderKey: params.parentFolderState.folderKey,
 563→    ipnsPrivateKey: params.parentFolderState.ipnsPrivateKey,
 564→    ipnsName: params.parentFolderState.ipnsName,
 565→    sequenceNumber: params.parentFolderState.sequenceNumber,
 566→  });
 567→
 568→  // 5. Batch publish: file IPNS record + folder IPNS record
 569→  const publishResult = await batchPublishIpnsRecords([
 570→    { ...params.fileIpnsRecord, recordType: 'file' },
 571→    folderResult.record,
 572→  ]);
 573→
 574→  if (publishResult.totalFailed > 0) {
 575→    console.error(
 576→      `Batch publish partial failure: ${publishResult.totalFailed}/${publishResult.totalFailed + publishResult.totalSucceeded} records failed`
 577→    );
 578→    throw new Error('Failed to publish one or more IPNS records');
 579→  }
 580→
 581→  return { filePointer, newSequenceNumber: folderResult.newSequenceNumber };
 582→}
 583→
 584→/**
 585→ * Add multiple files to a folder after successful upload (v2 batch).
 586→ *
 587→ * Creates FilePointer objects for all files, checks for name collisions,
 588→ * then publishes all N file IPNS records + 1 folder IPNS record via a
 589→ * single batch API call.
 590→ *
 591→ * @param params.parentFolderState - Parent folder to add files to
 592→ * @param params.files - Array of file data with pre-created IPNS records
 593→ * @returns Created file pointers and new sequence number
 594→ * @throws Error if any name collision exists
 595→ */
 596→export async function addFilesToFolder(params: {
 597→  parentFolderState: FolderNode;
 598→  files: Array<{
 599→    fileId: string;
 600→    name: string;
 601→    fileIpnsRecord: FileIpnsRecordPayload;
 602→    ipnsPrivateKeyEncrypted: string;
 603→  }>;
 604→}): Promise<{ filePointers: FilePointer[]; newSequenceNumber: bigint }> {
 605→  // 1. Build a set of existing child names for collision detection
 606→  const existingNames = new Set(params.parentFolderState.children.map((c) => c.name));
 607→
 608→  // 2. Create FilePointer for each file, checking collisions
 609→  const filePointers: FilePointer[] = [];
 610→  const now = Date.now();
 611→
 612→  for (const file of params.files) {
 613→    if (existingNames.has(file.name)) {
 614→      throw new Error(`A file with name "${file.name}" already exists`);
 615→    }
 616→    existingNames.add(file.name);
 617→
 618→    const filePointer: FilePointer = {
 619→      type: 'file',
 620→      id: file.fileId,
 621→      name: file.name,
 622→      fileMetaIpnsName: file.fileIpnsRecord.ipnsName,
 623→      ipnsPrivateKeyEncrypted: file.ipnsPrivateKeyEncrypted,
 624→      createdAt: now,
 625→      modifiedAt: now,
 626→    };
 627→    filePointers.push(filePointer);
 628→  }
 629→
 630→  // 3. Build updated children array
 631→  const children: FolderChild[] = [...params.parentFolderState.children, ...filePointers];
 632→
 633→  // 4. Build folder IPNS record
 634→  const folderResult = await buildFolderIpnsRecord({
 635→    children,
 636→    folderKey: params.parentFolderState.folderKey,
 637→    ipnsPrivateKey: params.parentFolderState.ipnsPrivateKey,
 638→    ipnsName: params.parentFolderState.ipnsName,
 639→    sequenceNumber: params.parentFolderState.sequenceNumber,
 640→  });
 641→
 642→  // 5. Batch publish: all N file IPNS records + 1 folder IPNS record (single API call)
 643→  const allRecords = [
 644→    ...params.files.map((f) => ({ ...f.fileIpnsRecord, recordType: 'file' as const })),
 645→    folderResult.record,
 646→  ];
 647→  const publishResult = await batchPublishIpnsRecords(allRecords);
 648→
 649→  if (publishResult.totalFailed > 0) {
 650→    console.error(
 651→      `Batch publish partial failure: ${publishResult.totalFailed}/${publishResult.totalFailed + publishResult.totalSucceeded} records failed`
 652→    );
 653→    throw new Error('Failed to publish one or more IPNS records');
 654→  }
 655→
 656→  return { filePointers, newSequenceNumber: folderResult.newSequenceNumber };
 657→}
 658→
 659→/**
 660→ * Replace file content in v2 metadata (content update).
 661→ *
 662→ * THIS IS THE PRIMARY BENEFIT OF PER-FILE IPNS: content updates publish
 663→ * ONLY the file's IPNS record. The folder metadata is NOT touched because
 664→ * the FilePointer still points to the same fileMetaIpnsName, which now
 665→ * resolves to the updated content.
 666→ *
 667→ * @param params.fileId - ID of file to update
 668→ * @param params.fileIpnsRecord - Updated file IPNS record from updateFileMetadata
 669→ * @param params.parentFolderState - Parent folder (used only to find the FilePointer)
 670→ * @returns Void -- no folder metadata update needed
 671→ * @throws Error if file not found
 672→ */
 673→export async function replaceFileInFolder(params: {
 674→  fileId: string;
 675→  fileIpnsRecord: FileIpnsRecordPayload;
 676→  parentFolderState: FolderNode;
 677→}): Promise<void> {
 678→  // 1. Verify file exists in parent's children
 679→  const fileExists = params.parentFolderState.children.some(
 680→    (c) => c.type === 'file' && c.id === params.fileId
 681→  );
 682→
 683→  if (!fileExists) throw new Error('File not found');
 684→
 685→  // 2. Publish ONLY the file IPNS record (folder metadata untouched!)
 686→  // This is the key optimization: content update does NOT modify folder metadata.
 687→  const publishResult = await batchPublishIpnsRecords([
 688→    { ...params.fileIpnsRecord, recordType: 'file' },
 689→  ]);
 690→
 691→  if (publishResult.totalFailed > 0) {
 692→    throw new Error('Failed to publish file IPNS record');
 693→  }
 694→}
 695→
 696→/**
 697→ * Calculate the maximum depth of a folder's subtree.
 698→ *
 699→ * Used to check if moving a folder would exceed the depth limit.
 700→ *
 701→ * @param folderId - Folder ID to calculate subtree depth for
 702→ * @param folders - Current folder tree
 703→ * @returns Maximum depth in the subtree (0 if folder has no children)
 704→ */
 705→export function calculateSubtreeDepth(
 706→  folderId: string,
 707→  folders: Record<string, FolderNode>
 708→): number {
 709→  const folder = folders[folderId];
 710→  if (!folder) return 0;
 711→
 712→  let maxChildDepth = 0;
 713→  for (const child of folder.children) {
 714→    if (child.type === 'folder') {
 715→      const childDepth = 1 + calculateSubtreeDepth(child.id, folders);
 716→      maxChildDepth = Math.max(maxChildDepth, childDepth);
 717→    }
 718→  }
 719→
 720→  return maxChildDepth;
 721→}
 722→
 723→/**
 724→ * Check if a folder is a descendant of a potential ancestor.
 725→ *
 726→ * Used to prevent moving a folder into itself or its descendants.
 727→ *
 728→ * @param folderId - Folder to check
 729→ * @param potentialAncestorId - Potential ancestor folder ID
 730→ * @param folders - Current folder tree
 731→ * @returns true if folderId is a descendant of potentialAncestorId
 732→ */
 733→export function isDescendantOf(
 734→  folderId: string,
 735→  potentialAncestorId: string,
 736→  folders: Record<string, FolderNode>
 737→): boolean {
 738→  let currentId: string | null = folderId;
 739→
 740→  while (currentId !== null) {
 741→    if (currentId === potentialAncestorId) return true;
 742→    const currentFolder: FolderNode | undefined = folders[currentId];
 743→    if (!currentFolder) break;
 744→    currentId = currentFolder.parentId;
 745→  }
 746→
 747→  return false;
 748→}
 749→
 750→/**
 751→ * Move a folder from one parent to another.
 752→ *
 753→ * Uses add-before-remove pattern to prevent data loss on failure.
 754→ * Validates depth limit and prevents moving folder into itself.
 755→ *
 756→ * @param params.folderId - ID of folder to move
 757→ * @param params.sourceFolderState - Current parent folder
 758→ * @param params.destFolderState - Destination parent folder
 759→ * @param params.folders - Full folder tree (for depth calculation)
 760→ * @throws Error if folder not found, name collision, depth limit exceeded,
 761→ *         or attempting to move folder into itself/descendant
 762→ */
 763→export async function moveFolder(params: {
 764→  folderId: string;
 765→  sourceFolderState: FolderNode;
 766→  destFolderState: FolderNode;
 767→  folders: Record<string, FolderNode>;
 768→}): Promise<{ destSequenceNumber: bigint; sourceSequenceNumber: bigint }> {
 769→  // 1. Find folder in source
 770→  const folder = params.sourceFolderState.children.find(
 771→    (c) => c.type === 'folder' && c.id === params.folderId
 772→  ) as FolderEntry | undefined;
 773→
 774→  if (!folder) throw new Error('Folder not found');
 775→
 776→  // 2. Check name collision in destination
 777→  const nameExists = params.destFolderState.children.some((c) => c.name === folder.name);
 778→  if (nameExists) throw new Error('An item with this name already exists in destination');
 779→
 780→  // 3. Check depth limit (20 levels max)
 781→  const destDepth = getDepth(params.destFolderState.id, params.folders);
 782→  const folderSubtreeDepth = calculateSubtreeDepth(params.folderId, params.folders);
 783→  if (destDepth + 1 + folderSubtreeDepth > MAX_FOLDER_DEPTH) {
 784→    throw new Error(`Cannot move: would exceed maximum folder depth of ${MAX_FOLDER_DEPTH}`);
 785→  }
 786→
 787→  // 4. Prevent moving folder into itself or its descendants
 788→  if (isDescendantOf(params.destFolderState.id, params.folderId, params.folders)) {
 789→    throw new Error('Cannot move folder into itself or its subfolder');
 790→  }
 791→
 792→  // 5. ADD to destination FIRST (add-before-remove pattern)
 793→  const destChildren: FolderChild[] = [
 794→    ...params.destFolderState.children,
 795→    {
 796→      ...folder,
 797→      modifiedAt: Date.now(),
 798→    },
 799→  ];
 800→
 801→  const { newSequenceNumber: destSequenceNumber } = await updateFolderMetadata({
 802→    folderId: params.destFolderState.id,
 803→    children: destChildren,
 804→    folderKey: params.destFolderState.folderKey,
 805→    ipnsPrivateKey: params.destFolderState.ipnsPrivateKey,
 806→    ipnsName: params.destFolderState.ipnsName,
 807→    sequenceNumber: params.destFolderState.sequenceNumber,
 808→  });
 809→
 810→  // 6. REMOVE from source AFTER destination confirmed
 811→  const sourceChildren = params.sourceFolderState.children.filter(
 812→    (c) => !(c.type === 'folder' && c.id === params.folderId)
 813→  );
 814→
 815→  const { newSequenceNumber: sourceSequenceNumber } = await updateFolderMetadata({
 816→    folderId: params.sourceFolderState.id,
 817→    children: sourceChildren,
 818→    folderKey: params.sourceFolderState.folderKey,
 819→    ipnsPrivateKey: params.sourceFolderState.ipnsPrivateKey,
 820→    ipnsName: params.sourceFolderState.ipnsName,
 821→    sequenceNumber:
 822→      params.sourceFolderState.id === params.destFolderState.id
 823→        ? destSequenceNumber
 824→        : params.sourceFolderState.sequenceNumber,
 825→  });
 826→
 827→  return { destSequenceNumber, sourceSequenceNumber };
 828→}
